//! Hopscotch hash table.
//!
//! Every key has a home bucket `hash & mask`. Its entry is guaranteed to live
//! in the *neighborhood* of that home bucket: the [`NEIGHBORHOOD_SIZE`]
//! buckets starting there. Each bucket carries a bitmap describing which
//! slots of its neighborhood hold entries that belong to it, so a lookup only
//! ever inspects the bits that are set.
//!
//! On insert, the first free slot at or after the home bucket is located and
//! then repeatedly *hopped* backwards - displacing entries that can afford to
//! move - until it falls inside the neighborhood. Entries that cannot be
//! placed that way spill into an overflow list.

use std::borrow::Borrow;
use std::hash::{BuildHasher, Hash, Hasher};

/// Number of buckets a home bucket may reach; also the width of the bitmap.
pub const NEIGHBORHOOD_SIZE: usize = 62;

/// Bucket count of the first allocated table (always a power of two).
const MIN_BUCKET_COUNT: usize = 16;

/// Table grows once this fraction of the buckets is occupied.
const MAX_LOAD_FACTOR: f32 = 0.95;

/// Table also grows once the overflow list gets this long, keeping the
/// linear scan over it negligible.
const MAX_OVERFLOW_LEN: usize = 8;

pub struct Bucket<K, V> {
    /// Bit `i` is set when bucket `self_index + i` holds an entry whose home
    /// bucket is `self_index`.
    neighborhood_info: u64,
    entry: Option<(K, V)>,
}

impl<K, V> Bucket<K, V> {
    fn empty() -> Self {
        Bucket {
            neighborhood_info: 0,
            entry: None,
        }
    }

    pub fn entry(&self) -> Option<&(K, V)> {
        self.entry.as_ref()
    }

    fn is_empty(&self) -> bool {
        self.entry.is_none()
    }
}

pub struct HopscotchHash<K, V, S> {
    /// `bucket_count + NEIGHBORHOOD_SIZE - 1` slots: the trailing ones let a
    /// neighborhood run past the end of the table without wrapping around.
    buckets: Vec<Bucket<K, V>>,
    bucket_count: usize,
    overflow: Vec<(K, V)>,
    nb_elements: usize,
    hash_builder: S,
    load_threshold: usize,
}

impl<K, V, S> HopscotchHash<K, V, S>
where
    K: Hash + Eq,
    S: BuildHasher,
{
    pub fn with_hasher(hash_builder: S) -> Self {
        HopscotchHash {
            buckets: Vec::new(),
            bucket_count: 0,
            overflow: Vec::new(),
            nb_elements: 0,
            hash_builder,
            load_threshold: 0,
        }
    }

    pub fn len(&self) -> usize {
        self.nb_elements
    }

    pub fn is_empty(&self) -> bool {
        self.nb_elements == 0
    }

    pub fn bucket_count(&self) -> usize {
        self.bucket_count
    }

    pub fn buckets(&self) -> &[Bucket<K, V>] {
        &self.buckets
    }

    pub fn overflow(&self) -> &[(K, V)] {
        &self.overflow
    }

    fn hash_of<Q>(&self, key: &Q) -> u64
    where
        Q: Hash + ?Sized,
    {
        let mut hasher = self.hash_builder.build_hasher();
        key.hash(&mut hasher);
        hasher.finish()
    }

    fn home_bucket(&self, hash: u64) -> usize {
        // bucket_count is a power of two, so the mask is exact.
        (hash & (self.bucket_count as u64 - 1)) as usize
    }

    /// Inserts the entry unless an equal key is already present.
    /// Returns `true` when the entry was inserted.
    pub fn insert(&mut self, key: K, value: V) -> bool {
        if self.nb_elements >= self.load_threshold || self.overflow.len() > MAX_OVERFLOW_LEN {
            self.grow();
        }

        let hash = self.hash_of(&key);
        let ibucket = self.home_bucket(hash);
        if self.find_in_neighborhood(ibucket, &key).is_some() || self.find_in_overflow(&key).is_some()
        {
            return false;
        }

        self.insert_new(ibucket, key, value);
        true
    }

    /// Places a key known to be absent, hopping a free slot into reach.
    fn insert_new(&mut self, ibucket: usize, key: K, value: V) {
        let mut iempty = ibucket;
        while iempty < self.buckets.len() && !self.buckets[iempty].is_empty() {
            iempty += 1;
        }

        if iempty < self.buckets.len() {
            while iempty - ibucket >= NEIGHBORHOOD_SIZE {
                match self.swap_empty_bucket_closer(iempty) {
                    Some(closer) => iempty = closer,
                    None => break,
                }
            }

            if iempty - ibucket < NEIGHBORHOOD_SIZE {
                self.buckets[iempty].entry = Some((key, value));
                self.buckets[ibucket].neighborhood_info |= 1u64 << (iempty - ibucket);
                self.nb_elements += 1;
                return;
            }
        }

        self.overflow.push((key, value));
        self.nb_elements += 1;
    }

    /// Moves an entry from a bucket that can spare it into `iempty`, so that
    /// the free slot travels backwards. Returns the new free slot.
    fn swap_empty_bucket_closer(&mut self, iempty: usize) -> Option<usize> {
        let start = iempty.saturating_sub(NEIGHBORHOOD_SIZE - 1);
        for ibucket in start..iempty {
            let mut info = self.buckets[ibucket].neighborhood_info;
            while info != 0 {
                let offset = info.trailing_zeros() as usize;
                let isource = ibucket + offset;
                if isource >= iempty {
                    break;
                }

                self.buckets[iempty].entry = self.buckets[isource].entry.take();
                self.buckets[ibucket].neighborhood_info &= !(1u64 << offset);
                self.buckets[ibucket].neighborhood_info |= 1u64 << (iempty - ibucket);
                return Some(isource);
            }
        }

        None
    }

    fn grow(&mut self) {
        let new_bucket_count = if self.bucket_count == 0 {
            MIN_BUCKET_COUNT
        } else {
            self.bucket_count * 2
        };

        let old_buckets = std::mem::replace(
            &mut self.buckets,
            Vec::with_capacity(new_bucket_count + NEIGHBORHOOD_SIZE - 1),
        );
        let old_overflow = std::mem::take(&mut self.overflow);

        self.buckets
            .resize_with(new_bucket_count + NEIGHBORHOOD_SIZE - 1, Bucket::empty);
        self.bucket_count = new_bucket_count;
        self.nb_elements = 0;
        self.load_threshold = (new_bucket_count as f32 * MAX_LOAD_FACTOR) as usize;

        for bucket in old_buckets {
            if let Some((key, value)) = bucket.entry {
                let ibucket = self.home_bucket(self.hash_of(&key));
                self.insert_new(ibucket, key, value);
            }
        }
        for (key, value) in old_overflow {
            let ibucket = self.home_bucket(self.hash_of(&key));
            self.insert_new(ibucket, key, value);
        }
    }

    fn find_in_neighborhood<Q>(&self, ibucket: usize, key: &Q) -> Option<usize>
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        let mut info = self.buckets[ibucket].neighborhood_info;
        while info != 0 {
            let offset = info.trailing_zeros() as usize;
            info &= info - 1;

            let icandidate = ibucket + offset;
            if let Some((candidate_key, _)) = &self.buckets[icandidate].entry {
                if candidate_key.borrow() == key {
                    return Some(icandidate);
                }
            }
        }

        None
    }

    fn find_in_overflow<Q>(&self, key: &Q) -> Option<usize>
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        self.overflow
            .iter()
            .position(|(candidate_key, _)| candidate_key.borrow() == key)
    }

    /// Position of `key` in the iteration order, or `None`.
    pub fn find_position<Q>(&self, key: &Q) -> Option<usize>
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        if self.bucket_count == 0 {
            return None;
        }

        let ibucket = self.home_bucket(self.hash_of(key));
        if let Some(index) = self.find_in_neighborhood(ibucket, key) {
            return Some(index);
        }

        self.find_in_overflow(key)
            .map(|index| self.buckets.len() + index)
    }

    pub fn value_at(&self, position: usize) -> Option<&(K, V)> {
        if position < self.buckets.len() {
            self.buckets[position].entry()
        } else {
            self.overflow.get(position - self.buckets.len())
        }
    }
}

/// Iteration walks the bucket array in order and then the overflow list, so a
/// position is a single index into that concatenation. `end` is the length of
/// the concatenation.
#[derive(Debug)]
pub struct Iter<'a, K, V> {
    buckets: &'a [Bucket<K, V>],
    overflow: &'a [(K, V)],
    position: usize,
}

impl<'a, K, V> Iter<'a, K, V> {
    pub fn new(buckets: &'a [Bucket<K, V>], overflow: &'a [(K, V)], position: usize) -> Self {
        let mut iter = Iter {
            buckets,
            overflow,
            position,
        };
        iter.skip_empty_buckets();
        iter
    }

    pub fn end(buckets: &'a [Bucket<K, V>], overflow: &'a [(K, V)]) -> Self {
        Iter {
            buckets,
            overflow,
            position: buckets.len() + overflow.len(),
        }
    }

    fn skip_empty_buckets(&mut self) {
        while self.position < self.buckets.len() && self.buckets[self.position].is_empty() {
            self.position += 1;
        }
    }

    fn is_end(&self) -> bool {
        self.position >= self.buckets.len() + self.overflow.len()
    }

    fn get(&self) -> Option<&'a (K, V)> {
        if self.is_end() {
            None
        } else if self.position < self.buckets.len() {
            self.buckets[self.position].entry()
        } else {
            self.overflow.get(self.position - self.buckets.len())
        }
    }

    /// `++it` in C++ terms: steps to the next entry, leaving the iterator at
    /// `end` once the table is exhausted.
    pub fn advance(&mut self) {
        if self.is_end() {
            return;
        }

        self.position += 1;
        self.skip_empty_buckets();
    }
}

impl<'a, K, V> Iterator for Iter<'a, K, V> {
    type Item = (&'a K, &'a V);

    fn next(&mut self) -> Option<Self::Item> {
        let entry = self.get()?;
        self.advance();
        Some((&entry.0, &entry.1))
    }
}

impl<'a, K, V> Clone for Iter<'a, K, V> {
    fn clone(&self) -> Self {
        Iter {
            buckets: self.buckets,
            overflow: self.overflow,
            position: self.position,
        }
    }
}

impl<'a, K, V> PartialEq for Iter<'a, K, V> {
    fn eq(&self, other: &Self) -> bool {
        self.position == other.position
    }
}

impl<'a, K, V> Eq for Iter<'a, K, V> {}

