//! `tsl::hopscotch_map` equivalent: a unique-key associative container built
//! on the hopscotch table in [`super::hopscotch_hash`].

use std::borrow::Borrow;
use std::hash::{BuildHasher, Hash};

use super::hash::FnvBuildHasher;
use super::hopscotch_hash::{HopscotchHash, Iter};

pub struct HopscotchMap<K, V, S = FnvBuildHasher> {
    ht: HopscotchHash<K, V, S>,
}

impl<K, V> HopscotchMap<K, V, FnvBuildHasher>
where
    K: Hash + Eq,
{
    pub fn new() -> Self {
        HopscotchMap::with_hasher(FnvBuildHasher)
    }
}

impl<K, V> Default for HopscotchMap<K, V, FnvBuildHasher>
where
    K: Hash + Eq,
{
    fn default() -> Self {
        HopscotchMap::new()
    }
}

impl<K, V, S> HopscotchMap<K, V, S>
where
    K: Hash + Eq,
    S: BuildHasher,
{
    pub fn with_hasher(hash_builder: S) -> Self {
        HopscotchMap {
            ht: HopscotchHash::with_hasher(hash_builder),
        }
    }

    /// `map.insert({key, value})`: keeps the existing entry when the key is
    /// already present. Returns whether the entry was inserted.
    pub fn insert(&mut self, entry: (K, V)) -> bool {
        let (key, value) = entry;
        self.ht.insert(key, value)
    }

    pub fn get<Q>(&self, key: &Q) -> Option<&V>
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        let position = self.ht.find_position(key)?;
        self.ht.value_at(position).map(|(_, value)| value)
    }

    pub fn contains_key<Q>(&self, key: &Q) -> bool
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        self.ht.find_position(key).is_some()
    }

    pub fn len(&self) -> usize {
        self.ht.len()
    }

    pub fn is_empty(&self) -> bool {
        self.ht.is_empty()
    }

    pub fn bucket_count(&self) -> usize {
        self.ht.bucket_count()
    }

    pub fn iter(&self) -> Iter<'_, K, V> {
        Iter::new(self.ht.buckets(), self.ht.overflow(), 0)
    }

    pub fn end(&self) -> Iter<'_, K, V> {
        Iter::end(self.ht.buckets(), self.ht.overflow())
    }

    pub fn find<Q>(&self, key: &Q) -> Iter<'_, K, V>
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        match self.ht.find_position(key) {
            Some(position) => Iter::new(self.ht.buckets(), self.ht.overflow(), position),
            None => self.end(),
        }
    }

    /// Range of entries equal to `key`. Keys are unique, so the range spans a
    /// single entry when the key is present and is empty otherwise.
    pub fn equal_range<Q>(&self, key: &Q) -> (Iter<'_, K, V>, Iter<'_, K, V>)
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        let first = self.find(key);
        let mut last = first.clone();
        last.advance();
        (first, last)
    }
}

