//! Small pieces of libstdc++ behaviour the C++ test relies on: `std::stoi`
//! parsing rules and the way an uncaught exception ends the process.

/// Mirrors the message libstdc++ prints from its terminate handler, then
/// aborts (SIGABRT), matching the C++ binary's exit status.
pub fn terminate_with(exception: &str, what: &str) -> ! {
    eprint!("terminate called after throwing an instance of '{exception}'\n  what():  {what}\n");
    std::process::abort()
}

/// `argv[index]` as `std::string`. Past the end of `argv` the C++ code reads
/// a null pointer, which makes the `std::string` constructor throw.
pub fn argv_at(args: &[String], index: usize) -> &str {
    match args.get(index) {
        Some(arg) => arg,
        None => terminate_with("std::logic_error", "basic_string::_S_construct null not valid"),
    }
}

fn is_space(byte: u8) -> bool {
    matches!(byte, b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r')
}

/// `std::stoi`: skips leading whitespace, accepts an optional sign and base-10
/// digits, and ignores whatever trails the number. Throws `invalid_argument`
/// when no digit was read and `out_of_range` when the value does not fit an
/// `int`.
pub fn stoi(text: &str) -> i32 {
    let bytes = text.as_bytes();
    let mut index = 0;

    while index < bytes.len() && is_space(bytes[index]) {
        index += 1;
    }

    let mut negative = false;
    if index < bytes.len() && (bytes[index] == b'+' || bytes[index] == b'-') {
        negative = bytes[index] == b'-';
        index += 1;
    }

    let first_digit = index;
    let mut accumulator: i64 = 0;
    let mut out_of_range = false;
    while index < bytes.len() && bytes[index].is_ascii_digit() {
        if !out_of_range {
            accumulator = accumulator * 10 + i64::from(bytes[index] - b'0');
            // Stop accumulating as soon as no int can hold the result; this
            // also keeps `accumulator` itself from overflowing.
            out_of_range = accumulator > -i64::from(i32::MIN);
        }
        index += 1;
    }

    if index == first_digit {
        terminate_with("std::invalid_argument", "stoi");
    }

    let value = if negative { -accumulator } else { accumulator };
    if out_of_range || value > i64::from(i32::MAX) || value < i64::from(i32::MIN) {
        terminate_with("std::out_of_range", "stoi");
    }

    value as i32
}

