/// Moves an entry from a bucket that can spare it into `iempty`, so that
/// the free slot travels backwards. Returns the new free slot.
fn swap_empty_bucket_closer(&mut self, iempty: usize) -> Option<usize> {
    let start = iempty.saturating_sub(NEIGHBORHOOD_SIZE - 1);
    for ibucket in start..iempty {
        let info = self.buckets[ibucket].neighborhood_info;
        if info == 0 {
            continue;
        }

        // The lowest set bit is this bucket's entry closest to it; if even
        // that one sits beyond `iempty` then none of them can move.
        let offset = info.trailing_zeros() as usize;
        let isource = ibucket + offset;
        if isource >= iempty {
            continue;
        }

        self.buckets[iempty].entry = self.buckets[isource].entry.take();
        self.buckets[ibucket].neighborhood_info &= !(1u64 << offset);
        self.buckets[ibucket].neighborhood_info |= 1u64 << (iempty - ibucket);
        return Some(isource);
    }

    None
}

