#[cfg(test)]
mod tests {
    use super::*;
    use std::hash::Hasher;

    /// Sends every key to the same home bucket, forcing neighborhood
    /// displacement and the overflow path.
    #[derive(Clone, Copy, Default)]
    struct ConstantBuildHasher;
    struct ConstantHasher;

    impl Hasher for ConstantHasher {
        fn write(&mut self, _bytes: &[u8]) {}
        fn finish(&self) -> u64 {
            0
        }
    }

    impl BuildHasher for ConstantBuildHasher {
        type Hasher = ConstantHasher;
        fn build_hasher(&self) -> ConstantHasher {
            ConstantHasher
        }
    }

    fn count_range<K: Hash + Eq, V, S: BuildHasher>(map: &HopscotchMap<K, V, S>, key: &K) -> usize {
        let (first, last) = map.equal_range(key);
        let mut it = first;
        let mut count = 0;
        while it != last {
            it.advance();
            count += 1;
        }
        count
    }

    #[test]
    fn empty_map_finds_nothing() {
        let map: HopscotchMap<i32, i32> = HopscotchMap::new();
        assert_eq!(map.len(), 0);
        assert!(map.is_empty());
        assert!(!map.contains_key(&0));
        assert_eq!(count_range(&map, &0), 0);
        assert_eq!(map.iter().count(), 0);
    }

    #[test]
    fn stores_and_retrieves_every_key() {
        let mut map: HopscotchMap<i32, i32> = HopscotchMap::new();
        for i in 0..5000 {
            assert!(map.insert((i, i * 12)));
        }

        assert_eq!(map.len(), 5000);
        for i in 0..5000 {
            assert_eq!(map.get(&i), Some(&(i * 12)), "key {i}");
            assert_eq!(count_range(&map, &i), 1, "key {i}");
        }
        for i in [-1, 5000, 12345] {
            assert!(!map.contains_key(&i));
            assert_eq!(count_range(&map, &i), 0);
        }
    }

    #[test]
    fn iteration_visits_each_entry_once() {
        let mut map: HopscotchMap<i32, i32> = HopscotchMap::new();
        for i in 0..2000 {
            map.insert((i, i * 12));
        }

        let mut seen: Vec<i32> = map
            .iter()
            .map(|(key, value)| {
                assert_eq!(*value, *key * 12);
                *key
            })
            .collect();
        seen.sort_unstable();
        assert_eq!(seen, (0..2000).collect::<Vec<_>>());
    }

    #[test]
    fn insert_keeps_the_first_value_for_a_duplicate_key() {
        let mut map: HopscotchMap<i32, i32> = HopscotchMap::new();
        assert!(map.insert((7, 84)));
        assert!(!map.insert((7, 99)));
        assert_eq!(map.len(), 1);
        assert_eq!(map.get(&7), Some(&84));
        assert_eq!(count_range(&map, &7), 1);
    }

    #[test]
    fn equal_range_end_matches_the_next_entry() {
        let mut map: HopscotchMap<i32, i32> = HopscotchMap::new();
        for i in 0..64 {
            map.insert((i, i * 12));
        }

        for i in 0..64 {
            let (first, last) = map.equal_range(&i);
            let mut next = first.clone();
            next.advance();
            assert!(next == last);
            assert_eq!(first.clone().next().map(|(k, _)| *k), Some(i));
        }
    }

    #[test]
    fn survives_colliding_hashes() {
        let mut map: HopscotchMap<i32, i32, ConstantBuildHasher> =
            HopscotchMap::with_hasher(ConstantBuildHasher);
        for i in 0..500 {
            assert!(map.insert((i, i * 12)));
        }

        assert_eq!(map.len(), 500);
        for i in 0..500 {
            assert_eq!(map.get(&i), Some(&(i * 12)), "key {i}");
            assert_eq!(count_range(&map, &i), 1, "key {i}");
        }
        assert_eq!(map.iter().count(), 500);
    }

    #[test]
    fn borrowed_keys_look_up_by_str() {
        let mut map: HopscotchMap<String, i32> = HopscotchMap::new();
        for i in 0..100 {
            map.insert((format!("key{i}"), i));
        }

        assert_eq!(map.get("key42"), Some(&42));
        assert!(!map.contains_key("missing"));
        assert_eq!(map.len(), 100);
    }
}
