/// Inserts the entry unless an equal key is already present.
/// Returns `true` when the entry was inserted.
pub fn insert(&mut self, key: K, value: V) -> bool {
    if self.nb_elements >= self.load_threshold || self.overflow_is_worth_rehashing() {
        self.grow();
    }

    let hash = self.hash_of(&key);
    let ibucket = self.home_bucket(hash);
    if self.find_in_neighborhood(ibucket, &key).is_some() || self.find_in_overflow(&key).is_some()
    {
        return false;
    }

    self.insert_new(ibucket, key, value);
    true
}

/// A long overflow list usually means the table is simply too full, and
/// growing spreads the entries out again. It can also mean many keys share
/// one home bucket, and then no amount of growing helps - so only grow
/// while the table is still reasonably loaded. Past that point the
/// overflow list is kept as-is rather than allocating without bound.
fn overflow_is_worth_rehashing(&self) -> bool {
    self.overflow.len() > MAX_OVERFLOW_LEN && self.nb_elements * 4 >= self.bucket_count
}

